namespace Esportra.Contracts.Air;

public sealed record AirPlayer(Guid Id, string OriginalName, string InGameName, string? GameId = null, string? HudNickname = null, string Role = "starter");
public sealed record AirTeam(Guid Id, string Name, string Tag, Guid? LogoAssetId, AirPlayer[] Players);
public sealed record AirMatch(Guid Id, string Title, Guid[] TeamIds, int BestOf, string[] MapPool, DateTimeOffset? ScheduledAt = null, string Status = "scheduled", int[]? Scores = null);
public sealed record AirScreen(Guid Id, string Title, string Type, string Overlay, Guid? MatchId = null);
public sealed record AirBracketNode(Guid Id, Guid MatchId, int Round, string Side = "upper", Guid? NextMatchId = null);
public sealed record AirBracketStage(Guid Id, string Label, string Format, AirBracketNode[] Matches);
public sealed record AirBracket(string Format, AirBracketStage[] Stages);
public sealed record AirSponsor(Guid Id, string Name, Guid? LogoAssetId = null);
public sealed record AirPerson(Guid Id, string Name, string Role);
public sealed record AirProjectDocument(int SchemaVersion, AirTeam[] Teams, AirMatch[] Matches, AirScreen[] Screens, AirBracket Bracket, AirSponsor[]? Sponsors = null, AirPerson[]? Talent = null, AirPerson[]? Crew = null);
public sealed record AirWorkspaceRequest(string Name);
public sealed record AirProjectRequest(string Title, AirProjectDocument Document, int Revision = 0, Guid? Id = null);
public sealed record AirDeviceRequest(Guid DeviceId, string Name, string Mode);
public sealed record AirAccessRequest(Guid DeviceId);
public sealed record AirPlanRequest(string Name, int? ProductionLimit = null, int? CaptureLimit = null, bool Enabled = true);
public sealed record AirGrantRequest(Guid PlanId, DateTimeOffset? ValidUntil, string Status, string Reason, bool OverrideDeviceLimits = false, int? ProductionLimit = null, int? CaptureLimit = null);
public sealed record AirReleaseRequest(string Version, string Channel, string DownloadUrl, string Notes, bool Published);
public sealed record AirWorkspaceView(Guid Id, string Name, DateTime CreatedAt);
public sealed record AirAccountSummary(Guid UserId, DateTime TrialStartedAt, DateTime TrialEndsAt, DateTime? ValidUntil, string Status, Guid PlanId);
public sealed record AirProjectSummary(Guid Id, Guid WorkspaceId, string Title, int Revision, DateTime UpdatedAt);
public sealed record AirAdminCustomer(Guid UserId, string Status, DateTime TrialStartedAt, DateTime TrialEndsAt, DateTime? ValidUntil, Guid PlanId, string Plan, string LicenseCode, int Revision, bool OverrideDeviceLimits, int? ProductionLimit, int? CaptureLimit);
public sealed record AirAdminWorkspace(Guid Id, string Name, Guid OwnerId, DateTime CreatedAt, long Projects);
public sealed record AirPlanView(Guid Id, string Name, int? ProductionLimit, int? CaptureLimit, bool Enabled);
public sealed record AirDeviceView(Guid Id, Guid UserId, string Name, string Mode, string Status, DateTime LastSeenAt, string Health, int Revision);
public sealed record AirAdminActivity(long Id, Guid ActorId, string Action, string SubjectId, string Reason, DateTime CreatedAt);
public sealed record AirReleaseView(Guid Id, string Version, string Channel, string DownloadUrl, string Notes, bool Published, DateTime CreatedAt);
public sealed record AirAdminCounts(long Customers, long Workspaces, long ActiveDevices, long OnlineDevices, long ExpiredAccess);
